//! Zenkai OS - Anti-Aliased DM Sans, Sora & Menlo Typography
//!
//! Author: Swapnil Ghosh 25BTRCL267 AIML-E
//! Pre-rasterized 8-bit grayscale coverage maps for crisp modern Linux-style UI.

#[derive(Clone, Copy)]
pub struct AaGlyph {
    pub advance: u8,
    pub width: u8,
    pub height: u8,
    pub offset: u32,
}

pub struct AaFace {
    pub line_height: usize,
    pub glyphs: &'static [AaGlyph],
    pub cov: &'static [u8],
}

impl AaFace {
    pub fn glyph(&self, ch: char) -> &'static AaGlyph {
        let b = ch as u32;
        if b >= 32 && b <= 126 {
            &self.glyphs[(b - 32) as usize]
        } else {
            &self.glyphs[('?' as u32 - 32) as usize]
        }
    }

    pub fn text_width(&self, text: &str) -> usize {
        text.chars().map(|c| self.glyph(c).advance as usize).sum()
    }
}
